const SIDE = 256;
const MAX_BYTES = 8 * 1024 * 1024;
const clock = new Intl.DateTimeFormat("ja-JP", { timeZone: "Asia/Tokyo", hour: "2-digit", minute: "2-digit", hourCycle: "h23" });

function composite(base: Buffer, overlay: Buffer) {
